#!/usr/bin/env bash
#
# arch-i3-rice.sh — GENERATED by build-rice.sh, do not edit by hand.
# Source of truth: https://github.com/thefoulowl/dotfiles
#
# Minimal dark i3 setup for Arch (X11): theme, picom, alacritty, rofi,
# dunst, themed ly login, i3lock without faillock lockouts, touchpad tap,
# Windows-style Alt+Tab, minimize/restore, one-window-at-a-time workflow.
#
# Safe to re-run: existing files are moved aside as *.bak-<timestamp>.
# Usage: ./arch-i3-rice.sh

set -euo pipefail

# ---- palette: change these to retheme everything ----
BG="#101014"
FG="#d8d8dc"
ACCENT="#7aa2f7"
MUTED="#44475a"
URGENT="#f7768e"

TS="$(date +%Y%m%d-%H%M%S)"
backup() { if [ -e "$1" ] && [ ! -L "$1" ]; then mv "$1" "$1.bak-$TS"; echo "    (backed up existing -> $1.bak-$TS)"; fi; }
palette() {
    sed -i \
        -e "s/101014/${BG#\#}/g" \
        -e "s/d8d8dc/${FG#\#}/g" \
        -e "s/7aa2f7/${ACCENT#\#}/g" \
        -e "s/44475a/${MUTED#\#}/g" \
        -e "s/f7768e/${URGENT#\#}/g" \
        "$1"
}

echo "==> Installing packages (sudo)"
sudo pacman -S --needed --noconfirm \
    i3-wm i3status dmenu alacritty xorg-server xorg-xinit \
    picom ttf-jetbrains-mono-nerd \
    i3lock xss-lock maim brightnessctl rofi dunst libnotify \
    ly python
mkdir -p ~/Pictures

echo "==> Writing user configs"
echo "  $HOME/.config/i3/config"
mkdir -p "$(dirname $HOME/.config/i3/config)"
backup $HOME/.config/i3/config
cat > $HOME/.config/i3/config <<'__DOTFILE_EOF__'
# This file has been auto-generated by i3-config-wizard(1).
# It will not be overwritten, so edit it as you like.
#
# Should you change your keyboard layout some time, delete
# this file and re-run i3-config-wizard(1).
#

# i3 config file (v4)
#
# Please see https://i3wm.org/docs/userguide.html for a complete reference!

set $mod Mod4

# i3 defaults this to "yes", meaning the cursor merely passing over a window
# focuses it. That was silently corrupting the Alt+Tab history (mouse drift
# counted as a deliberate switch) — keyboard/clicks only, going forward.
focus_follows_mouse no

# Font for window titles. Will also be used by the bar unless a different font
# is used in the bar {} block below.
font pango:JetBrainsMono Nerd Font 10

# --- theme: dark minimal ---
set $bg     #101014
set $fg     #d8d8dc
set $accent #7aa2f7
set $muted  #44475a
set $urgent #f7768e

gaps inner 12
gaps outer 4
smart_gaps on
smart_borders on

for_window [class="^.*"] border pixel 2
default_border pixel 2
default_floating_border pixel 2

# class                 border    backgr.   text   indicator  child_border
client.focused           $accent   $accent   $bg    $accent    $accent
client.focused_inactive  $muted    $muted    $fg    $muted     $muted
client.unfocused         $muted    $bg       $fg    $muted     $bg
client.urgent            $urgent   $urgent   $bg    $urgent    $urgent

exec --no-startup-id picom --config ~/.config/picom/picom.conf
exec --no-startup-id xsetroot -solid $bg
# focus-history daemon runs as a systemd --user service instead (more reliable
# than i3's own exec autostart, which wasn't firing reliably on this machine
# for `i3-msg restart` — see i3-focus-history.service)

# screen lock (xss-lock) and notifications (dunst) run as systemd --user
# services instead — i3's own exec autostart isn't reliable on this machine
# for `i3-msg restart` (see i3-focus-history.service for the same fix)

# Use pactl to adjust volume in PulseAudio.
set $refresh_i3status killall -SIGUSR1 i3status
bindsym XF86AudioRaiseVolume exec --no-startup-id pactl set-sink-volume @DEFAULT_SINK@ +10% && $refresh_i3status
bindsym XF86AudioLowerVolume exec --no-startup-id pactl set-sink-volume @DEFAULT_SINK@ -10% && $refresh_i3status
bindsym XF86AudioMute exec --no-startup-id pactl set-sink-mute @DEFAULT_SINK@ toggle && $refresh_i3status
bindsym XF86AudioMicMute exec --no-startup-id pactl set-source-mute @DEFAULT_SOURCE@ toggle && $refresh_i3status

# Brightness
bindsym XF86MonBrightnessUp exec --no-startup-id brightnessctl set +10%
bindsym XF86MonBrightnessDown exec --no-startup-id brightnessctl set 10%-

# Screenshots (maim): full screen / region select
bindsym $mod+p exec --no-startup-id maim ~/Pictures/screenshot-$(date +%Y%m%d-%H%M%S).png
bindsym $mod+Shift+p exec --no-startup-id maim -s ~/Pictures/screenshot-$(date +%Y%m%d-%H%M%S).png

# Lock screen
bindsym $mod+Shift+x exec --no-startup-id i3lock -c 101014

# Use Mouse+$mod to drag floating windows to their wanted position
floating_modifier $mod

# move tiling windows via drag & drop by left-clicking into the title bar,
# or left-clicking anywhere into the window while holding the floating modifier.
tiling_drag modifier titlebar

# toggling a tiled window to floating keeps its current (often small) tiled
# size — enforce a floor so it doesn't end up tiny/short.
floating_minimum_size 800 x 500

# start a terminal
# i3 refuses to auto-focus a NEW window while the current one is fullscreen
# (by design, so a video/game isn't interrupted) — drop fullscreen first so
# the new terminal actually gets focus, and shows up in Alt+Tab immediately.
bindsym $mod+Return fullscreen disable; exec alacritty
# ...and every new app window opens as its own maximized window rather than
# splitting the screen with whatever was already there. Scoped to "normal"
# windows so dialogs, file pickers and popups keep their natural size.
for_window [window_type="normal"] fullscreen enable, focus

# kill focused window
bindsym $mod+Shift+q kill

# start dmenu (a program launcher)
bindsym $mod+d exec --no-startup-id dmenu_run -nb "$bg" -nf "$fg" -sb "$accent" -sf "$bg" -fn "JetBrainsMono Nerd Font:size=10"

# tap Super alone (no other key) to also open the launcher, Windows-key
# style — xcape (systemd service) turns a solo Super tap into the Menu
# keysym (an unused laptop key), since $mod+anything still needs to work
# normally as every other shortcut
bindsym Menu exec --no-startup-id dmenu_run -nb "$bg" -nf "$fg" -sb "$accent" -sf "$bg" -fn "JetBrainsMono Nerd Font:size=10"
# A more modern dmenu replacement is rofi:
# bindcode $mod+40 exec "rofi -modi drun,run -show drun"
# There also is i3-dmenu-desktop which only displays applications shipping a
# .desktop file. It is a wrapper around dmenu, so you need that installed.
# bindcode $mod+40 exec --no-startup-id i3-dmenu-desktop

# change focus
bindsym $mod+j focus left
bindsym $mod+k focus down
bindsym $mod+l focus up
bindsym $mod+semicolon focus right

# alternatively, you can use the cursor keys:
bindsym $mod+Left focus left
bindsym $mod+Down focus down
bindsym $mod+Up focus up
bindsym $mod+Right focus right

# move focused window
bindsym $mod+Shift+j move left
bindsym $mod+Shift+k move down
bindsym $mod+Shift+l move up
bindsym $mod+Shift+semicolon move right

# alternatively, you can use the cursor keys:
bindsym $mod+Shift+Left move left
bindsym $mod+Shift+Down move down
bindsym $mod+Shift+Up move up
bindsym $mod+Shift+Right move right

# split in horizontal orientation
bindsym $mod+h split h

# split in vertical orientation
bindsym $mod+v split v

# enter fullscreen mode for the focused container
bindsym $mod+f fullscreen toggle

# change container layout (stacked, tabbed, toggle split)
bindsym $mod+s layout stacking
bindsym $mod+w layout tabbed
bindsym $mod+e layout toggle split

# toggle tiling / floating
bindsym $mod+Shift+space floating toggle

# change focus between tiling / floating windows
bindsym $mod+space focus mode_toggle

# focus the parent container
bindsym $mod+a focus parent

# focus the child container
#bindsym $mod+d focus child

# minimize / restore via the scratchpad.
# i3 refuses "move scratchpad" on a fullscreen window, so always drop
# fullscreen first. (Shift+minus is the "underscore" keysym on a US layout.)
bindsym $mod+minus fullscreen disable, move scratchpad; fullscreen enable
bindsym $mod+Shift+underscore exec --no-startup-id python3 ~/.config/i3/scripts/focus_history.py --restore

# minimize every window on the current workspace at once (show-desktop)
bindsym $mod+m fullscreen disable; [workspace="__focused__"] move scratchpad

# Alt+Tab, Windows-style: hold Alt, tap Tab to step through windows in
# most-recently-used order (Shift+Tab steps back), release Alt to land.
# (key auto-repeat is throttled inside the script)
bindsym Mod1+Tab exec --no-startup-id python3 ~/.config/i3/scripts/focus_history.py --tab
bindsym Mod1+Shift+Tab exec --no-startup-id python3 ~/.config/i3/scripts/focus_history.py --tab-back
bindsym --release Alt_L exec --no-startup-id python3 ~/.config/i3/scripts/focus_history.py --release
bindsym --release Alt_R exec --no-startup-id python3 ~/.config/i3/scripts/focus_history.py --release

# full fuzzy window list (any workspace) when you'd rather pick by name
bindsym $mod+Shift+Tab exec --no-startup-id rofi -show window

# cycle to previously focused workspace
bindsym $mod+Tab workspace back_and_forth

# Define names for default workspaces for which we configure key bindings later on.
# We use variables to avoid repeating the names in multiple places.
set $ws1 "1"
set $ws2 "2"
set $ws3 "3"
set $ws4 "4"
set $ws5 "5"
set $ws6 "6"
set $ws7 "7"
set $ws8 "8"
set $ws9 "9"
set $ws10 "10"

# switch to workspace
bindsym $mod+1 workspace number $ws1
bindsym $mod+2 workspace number $ws2
bindsym $mod+3 workspace number $ws3
bindsym $mod+4 workspace number $ws4
bindsym $mod+5 workspace number $ws5
bindsym $mod+6 workspace number $ws6
bindsym $mod+7 workspace number $ws7
bindsym $mod+8 workspace number $ws8
bindsym $mod+9 workspace number $ws9
bindsym $mod+0 workspace number $ws10

# move focused container to workspace
bindsym $mod+Shift+1 move container to workspace number $ws1
bindsym $mod+Shift+2 move container to workspace number $ws2
bindsym $mod+Shift+3 move container to workspace number $ws3
bindsym $mod+Shift+4 move container to workspace number $ws4
bindsym $mod+Shift+5 move container to workspace number $ws5
bindsym $mod+Shift+6 move container to workspace number $ws6
bindsym $mod+Shift+7 move container to workspace number $ws7
bindsym $mod+Shift+8 move container to workspace number $ws8
bindsym $mod+Shift+9 move container to workspace number $ws9
bindsym $mod+Shift+0 move container to workspace number $ws10

# reload the configuration file
bindsym $mod+Shift+c reload
# restart i3 inplace (preserves your layout/session, can be used to upgrade i3)
bindsym $mod+Shift+r restart
# exit i3 (logs you out of your X session)
bindsym $mod+Shift+e exec "i3-nagbar -t warning -m 'You pressed the exit shortcut. Do you really want to exit i3? This will end your X session.' -B 'Yes, exit i3' 'i3-msg exit'"

# resize window (you can also use the mouse for that)
mode "resize" {
        # These bindings trigger as soon as you enter the resize mode

        # Pressing left will shrink the window’s width.
        # Pressing right will grow the window’s width.
        # Pressing up will shrink the window’s height.
        # Pressing down will grow the window’s height.
        bindsym j resize shrink width 10 px or 10 ppt
        bindsym k resize grow height 10 px or 10 ppt
        bindsym l resize shrink height 10 px or 10 ppt
        bindsym semicolon resize grow width 10 px or 10 ppt

        # same bindings, but for the arrow keys
        bindsym Left resize shrink width 10 px or 10 ppt
        bindsym Down resize grow height 10 px or 10 ppt
        bindsym Up resize shrink height 10 px or 10 ppt
        bindsym Right resize grow width 10 px or 10 ppt

        # back to normal: Enter or Escape or $mod+r
        bindsym Return mode "default"
        bindsym Escape mode "default"
        bindsym $mod+r mode "default"
}

bindsym $mod+r mode "resize"

# Start i3bar to display a workspace bar (plus the system information i3status
# finds out, if available)
bar {
        status_command i3status
        font pango:JetBrainsMono Nerd Font 10
        position bottom
        separator_symbol " | "
        colors {
                background $bg
                statusline $fg
                separator  $muted

                focused_workspace  $accent $accent $bg
                active_workspace   $muted  $muted  $fg
                inactive_workspace $bg     $bg     $muted
                urgent_workspace   $urgent $urgent $bg
        }
}
