* {
    bg:      #101014;
    bg-alt:  #17171c;
    fg:      #d8d8dc;
    accent:  #7aa2f7;
    muted:   #44475a;

    background-color: @bg;
    text-color:        @fg;
    border-color:      @accent;
}

window {
    width: 40%;
    border: 2px;
    border-radius: 6px;
    padding: 12px;
    background-color: @bg;
}

mainbox {
    children: [ inputbar, listview ];
    spacing: 10px;
}

inputbar {
    background-color: @bg-alt;
    text-color: @fg;
    padding: 8px 10px;
    border-radius: 4px;
}

listview {
    lines: 8;
    scrollbar: false;
    spacing: 4px;
}

element {
    padding: 6px 10px;
    border-radius: 4px;
}

element selected {
    background-color: @accent;
    text-color: @bg;
}
__DOTFILE_EOF__
chmod 644 $HOME/.config/rofi/config.rasi
palette $HOME/.config/rofi/config.rasi
echo "  $HOME/.config/i3status/config"
mkdir -p "$(dirname $HOME/.config/i3status/config)"
backup $HOME/.config/i3status/config
cat > $HOME/.config/i3status/config <<'__DOTFILE_EOF__'
general {
        colors = true
        interval = 5
        color_good = "#7aa2f7"
        color_degraded = "#e0af68"
        color_bad = "#f7768e"
}

order += "wireless _first_"
order += "ethernet _first_"
order += "battery all"
order += "memory"
order += "tztime local"

wireless _first_ {
        format_up = " %essid"
        format_down = " down"
}

ethernet _first_ {
        format_up = " %ip"
        format_down = ""
}

battery all {
        format = "%status %percentage"
        format_down = ""
        status_chr = ""
        status_bat = ""
        status_full = ""
        low_threshold = 15
}

memory {
        format = " %used"
        threshold_degraded = "1G"
        format_degraded = " %available"
}

tztime local {
        format = " %Y-%m-%d  %H:%M"
}
__DOTFILE_EOF__
chmod 644 $HOME/.config/i3status/config
palette $HOME/.config/i3status/config
echo "  $HOME/.config/dunst/dunstrc"
