chmod 644 $HOME/.config/dunst/dunstrc
palette $HOME/.config/dunst/dunstrc
echo "  $HOME/.config/systemd/user/i3-focus-history.service"
mkdir -p "$(dirname $HOME/.config/systemd/user/i3-focus-history.service)"
