cat > $HOME/.config/systemd/user/i3-focus-history.service <<'__DOTFILE_EOF__'
[Unit]
Description=i3 focus-history daemon for Alt+Tab cycling
After=graphical-session.target

[Service]
Type=simple
Environment=DISPLAY=:0
ExecStart=/usr/bin/python3 %h/.config/i3/scripts/focus_history.py --daemon
Restart=always
RestartSec=2

[Install]
WantedBy=default.target
__DOTFILE_EOF__
chmod 644 $HOME/.config/systemd/user/i3-focus-history.service
palette $HOME/.config/systemd/user/i3-focus-history.service
echo "  $HOME/.config/systemd/user/battery-warn.service"
